from typing import List

def xShape(grid: List[List[str]]) -> int:
    def dfs(i: int, j: int) -> None:
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] != 'X':
            return
        grid[i][j] = 'O'
        dfs(i + 1, j)
        dfs(i - 1, j)
        dfs(i, j + 1)
        dfs(i, j - 1)

    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 'X':
                dfs(i, j)
                count += 1
    return count
